<?php declare(strict_types=1);$base=config('app.base_path');$isTrash=!empty($trash); ?><div class="page-header"><div><h1><?= $isTrash?'Deleted Fresh Food Categories':'Fresh Food Categories' ?></h1><p>Manage categories per Fresh Food business.</p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/categories">Active Categories</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/categories?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/fresh-food/categories/create">Add Category</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Business</th><th>Category</th><th>Products</th><th>Order</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(empty($categories)): ?><tr><td colspan="6"><div class="empty-state">No categories found.</div></td></tr><?php else:foreach($categories as $c): ?><tr><td><?= htmlspecialchars((string)$c['business_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)$c['name'],ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$c['product_count'] ?></td><td><?= (int)$c['sort_order'] ?></td><td><?= htmlspecialchars((string)$c['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($isTrash): ?><form method="post" action="<?= $base ?>/fresh-food/categories/<?= (int)$c['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/fresh-food/categories/<?= (int)$c['id'] ?>/edit">Edit</a> <form method="post" action="<?= $base ?>/fresh-food/categories/<?= (int)$c['id'] ?>/delete" style="display:inline"><button class="link-button" onclick="return confirm('Delete this category?')">Delete</button></form><?php endif; ?></td></tr><?php endforeach;endif; ?></tbody></table></div>
